\begin{tikzpicture}[xscale=1.3, yscale=1.1, >=stealth]
  % Axis
  \draw[->, thick] (-0.5,0) -- (6.8,0) node[right] {\(x\)};

  % Solid outline profile
  \draw[thick, fill=gray!10] (0,1.5) .. controls (2,2.2) and (4,1.2) .. (6,1.5)
    -- (6,-1.5) .. controls (4,-1.2) and (2,-2.2) .. (0,-1.5) -- cycle;

  % Left cap
  \draw[thick, fill=gray!25] (0,0) ellipse (0.35 and 1.5);

  % Highlighted slice between x=3 and x=3.5
  \draw[thick, fill=gray!35] (3.5,0) ellipse (0.38 and 1.6);
  \draw[thick, fill=gray!50] (3,1.6) .. controls (3.2,1.65) .. (3.5,1.6)
    -- (3.5,-1.6) .. controls (3.2,-1.65) .. (3,-1.6) -- cycle;
  \draw[thick, fill=gray!40] (3.5,0) ellipse (0.38 and 1.6);

  % Right cap (dashed back, solid front)
  \draw[thick, dashed] (6,1.5) arc (90:270:0.35 and 1.5);
  \draw[thick] (6,-1.5) arc (-90:90:0.35 and 1.5);

  % Ticks and labels on x-axis
  \draw[thick] (0,0.1) -- (0,-0.1) node[below=8pt] {\(a\)};
  \draw[thick] (3,0.1) -- (3,-0.1) node[below=8pt] {\(x\)};
  \draw[thick] (3.5,0.1) -- (3.5,-0.1) node[below=8pt] {\(x+\Delta x\)};
  \draw[thick] (6,0.1) -- (6,-0.1) node[below=8pt] {\(b\)};

  % Dimension bracket for Delta x at top
  \draw[thick] (3,1.9) -- (3,2.2);
  \draw[thick] (3.5,1.9) -- (3.5,2.2);
  \draw[thick, <->] (3,2.05) -- (3.5,2.05) node[midway, above] {\(\Delta x\)};

  % Area label on slice face
  \node at (3.5,0) {\small area \(A(x)\)};

  % Volume annotation
  \draw[thick, <-] (3.25,-1.7) -- (3.25,-2.3) node[below] {volume \(\approx A(x)\Delta x\)};
\end{tikzpicture}

\begin{tikzpicture}[xscale=1.6, yscale=1.1, >=stealth]
  % Axis
  \draw[->, thick] (-0.3,0) -- (4.7,0) node[right] {\(x\)};
  \draw[->, thick] (0,-2.5) -- (0,2.5) node[above] {\(y\)};

  % Solid surface outline y = sqrt(x) and y = -sqrt(x)
  \draw[thick, domain=0:4, samples=100, fill=gray!15] plot (\x, {sqrt(\x)})
    -- (4, -2) plot[domain=4:0, samples=100] (\x, {-sqrt(\x)}) -- cycle;

  % Upper curve emphasized
  \draw[very thick, domain=0:4, samples=100] plot (\x, {sqrt(\x)});
  \node[anchor=south] at (1.8, 1.45) {\(y=\sqrt{x}\)};

  % Slice at x=2.5
  \draw[thick, fill=gray!45] (2.5,0) ellipse (0.35 and 1.58);
  \draw[thick, fill=gray!60] (2.4,1.55) -- (2.5,1.58) -- (2.5,-1.58) -- (2.4,-1.55) -- cycle;
  \draw[thick, fill=gray!40] (2.5,0) ellipse (0.35 and 1.58);

  % End cap at x=4
  \draw[thick, dashed] (4,2) arc (90:270:0.45 and 2);
  \draw[thick] (4,-2) arc (-90:90:0.45 and 2);

  % Radius line
  \draw[thick, <->] (2.5,0) -- (2.5,1.58) node[midway, right] {radius \(\sqrt{x}\)};

  % X ticks
  \draw[thick] (0,0.1) -- (0,-0.1) node[below left] {\(0\)};
  \draw[thick] (2.5,0.1) -- (2.5,-0.1) node[below=8pt] {\(x\)};
  \draw[thick] (4,0.1) -- (4,-0.1) node[below=8pt] {\(4\)};

  % Rotation arrow around x axis
  \draw[->, thick] (4.4,0.5) arc (60:300:0.3 and 0.5);
  \node[anchor=north] at (2.5,-2.2) {rotation around \(x\)-axis};
\end{tikzpicture}

\begin{tikzpicture}[xscale=1.4, yscale=1.1, >=stealth]
  % Axes
  \draw[->, thick] (-2.8,0) -- (2.8,0) node[right] {\(x\)};
  \draw[->, thick] (0,-0.4) -- (0,4.8) node[above] {\(y\)};

  % Solid surface of revolution for y = x^2 (paraboloid) up to y=4
  \draw[thick, domain=0:2, samples=100, fill=gray!15] plot (\x, {\x*\x})
    -- (-2, 4) plot[domain=-2:0, samples=100] (\x, {\x*\x}) -- cycle;

  % Paraboloid outer curve
  \draw[very thick, domain=-2:2, samples=100] plot (\x, {\x*\x});

  % Top cap at y=4
  \draw[thick, fill=gray!25] (0,4) ellipse (2 and 0.45);

  % Horizontal slice at y=2.2
  \draw[thick, fill=gray!50] (0,2.2) ellipse (1.48 and 0.35);
  \draw[thick, fill=gray!60] (-1.41,2.0) -- (-1.48,2.2) -- (1.48,2.2) -- (1.41,2.0) -- cycle;
  \draw[thick, fill=gray!40] (0,2.2) ellipse (1.48 and 0.35);

  % Annotations
  \draw[thick, <->] (0,2.2) -- (1.48,2.2) node[midway, above] {\small radius \(\sqrt{y}\)};
  \node at (0,2.2) [below=8pt] {\small area \(A(y)\)};

  % Thickness Delta y annotation
  \draw[thick, <-] (1.45,2.1) -- (2.3,2.1) node[right] {\(\Delta y\)};
  \draw[thick, <-] (0,1.2) -- (-1.8,1.2) node[left] {volume \(\approx A(y)\Delta y\)};

  % Labels
  \node[anchor=west] at (1.6, 2.8) {\(x=\sqrt{y}\)};
  \node[anchor=south west] at (0.5, 4.0) {\(y=4\)};

  % Rotation arrow around y axis
  \draw[->, thick] (0.4,4.5) arc (30:330:0.4 and 0.2);
  \node[anchor=east] at (-0.5,4.5) {rotation around \(y\)-axis};
\end{tikzpicture}
